import 'package:flutter/material.dart';
import '../colors/app_colors.dart';
import '../typography/app_typography.dart';
import '../spacing/app_spacing.dart';
import 'app_card.dart';/// Enhanced dashboard components for the School Dynamics home screen/// Features modern card-based architecture with quick stats and activity feedsclass DashboardComponents {  DashboardComponents._();  /// Creates a quick stats section with key metrics  static Widget buildQuickStats({    required List<StatItem> stats,    int crossAxisCount = 2,  }) {    return GridView.builder(      shrinkWrap: true,      physics: const NeverScrollableScrollPhysics(),      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(        crossAxisCount: crossAxisCount,        crossAxisSpacing: AppSpacing.sm,        mainAxisSpacing: AppSpacing.sm,        childAspectRatio: 1.5,      ),      itemCount: stats.length,      itemBuilder: (context, index) {        final stat = stats[index];        return QuickStatCard(stat: stat);      },    );  }  /// Creates a recent activity feed  static Widget buildActivityFeed({    required List<ActivityItem> activities,    int maxItems = 5,    VoidCallback? onViewAll,  }) {    return AppCard(      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          Row(            mainAxisAlignment: MainAxisAlignment.spaceBetween,            children: [              Text(                'Recent Activity',                style: AppTypography.headlineSmall.copyWith(                  fontWeight: FontWeight.w600,                ),              ),              if (onViewAll != null)                TextButton(                  onPressed: onViewAll,                  child: Text(                    'View All',                    style: AppTypography.bodyMedium.copyWith(                      color: AppColors.primary,                      fontWeight: FontWeight.w500,                    ),                  ),                ),            ],          ),          AppSpacing.gapSM,          ...activities.take(maxItems).map((activity) => ActivityListItem(                activity: activity,                isLast: activity == activities.take(maxItems).last,              )),        ],      ),    );  }  /// Creates contextual action buttons  static Widget buildQuickActions({    required List<QuickAction> actions,  }) {    return AppCard(      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          Text(            'Quick Actions',            style: AppTypography.headlineSmall.copyWith(              fontWeight: FontWeight.w600,            ),          ),          AppSpacing.gapSM,          Wrap(            spacing: AppSpacing.xs,            runSpacing: AppSpacing.xs,            children: actions.map((action) => QuickActionChip(              action: action,            )).toList(),          ),        ],      ),    );  }}/// Quick stat card widgetclass QuickStatCard extends StatelessWidget {  final StatItem stat;  const QuickStatCard({    Key? key,    required this.stat,  }) : super(key: key);  @override  Widget build(BuildContext context) {    return AppCard(      padding: const EdgeInsets.all(AppSpacing.md),      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        mainAxisAlignment: MainAxisAlignment.spaceBetween,        children: [          Row(            mainAxisAlignment: MainAxisAlignment.spaceBetween,            children: [              Container(                padding: const EdgeInsets.all(AppSpacing.xs),                decoration: BoxDecoration(                  color: stat.color.withOpacity(0.1),                  borderRadius: BorderRadius.circular(AppSpacing.xs),                ),                child: Icon(                  stat.icon,                  color: stat.color,                  size: 20,                ),              ),              if (stat.trend != null)                TrendIndicator(trend: stat.trend!),            ],          ),          Column(            crossAxisAlignment: CrossAxisAlignment.start,            children: [              Text(                stat.value,                style: AppTypography.headlineMedium.copyWith(                  fontWeight: FontWeight.bold,                  color: AppColors.textPrimary,                ),              ),              Text(                stat.label,                style: AppTypography.bodySmall.copyWith(                  color: AppColors.textSecondary,                ),                maxLines: 1,                overflow: TextOverflow.ellipsis,              ),            ],          ),        ],      ),    );  }}/// Activity list item widgetclass ActivityListItem extends StatelessWidget {  final ActivityItem activity;  final bool isLast;  const ActivityListItem({    Key? key,    required this.activity,    this.isLast = false,  }) : super(key: key);  @override  Widget build(BuildContext context) {    return Container(      padding: const EdgeInsets.symmetric(vertical: AppSpacing.sm),      decoration: BoxDecoration(        border: isLast            ? null            : Border(                bottom: BorderSide(                  color: AppColors.border.withOpacity(0.5),                  width: 1,                ),              ),      ),      child: Row(        children: [          Container(            width: 40,            height: 40,            decoration: BoxDecoration(              color: activity.color.withOpacity(0.1),              shape: BoxShape.circle,            ),            child: Icon(              activity.icon,              color: activity.color,              size: 20,            ),          ),          AppSpacing.hGapSM,          Expanded(            child: Column(              crossAxisAlignment: CrossAxisAlignment.start,              children: [                Text(                  activity.title,                  style: AppTypography.bodyMedium.copyWith(                    fontWeight: FontWeight.w500,                  ),                  maxLines: 1,                  overflow: TextOverflow.ellipsis,                ),                if (activity.subtitle != null)                  Text(                    activity.subtitle!,                    style: AppTypography.bodySmall.copyWith(                      color: AppColors.textSecondary,                    ),                    maxLines: 1,                    overflow: TextOverflow.ellipsis,                  ),              ],            ),          ),          Text(            activity.timestamp,            style: AppTypography.labelSmall.copyWith(              color: AppColors.textSecondary,            ),          ),        ],      ),    );  }}/// Quick action chip widgetclass QuickActionChip extends StatelessWidget {  final QuickAction action;  const QuickActionChip({    Key? key,    required this.action,  }) : super(key: key);  @override  Widget build(BuildContext context) {    return InkWell(      onTap: action.onTap,      borderRadius: BorderRadius.circular(AppSpacing.lg),      child: Container(        padding: const EdgeInsets.symmetric(          horizontal: AppSpacing.md,          vertical: AppSpacing.sm,        ),        decoration: BoxDecoration(          color: action.color.withOpacity(0.1),          borderRadius: BorderRadius.circular(AppSpacing.lg),          border: Border.all(            color: action.color.withOpacity(0.3),            width: 1,          ),        ),        child: Row(          mainAxisSize: MainAxisSize.min,          children: [            Icon(              action.icon,              color: action.color,              size: 16,            ),            const SizedBox(width: AppSpacing.xs),            Text(              action.label,              style: AppTypography.labelMedium.copyWith(                color: action.color,                fontWeight: FontWeight.w500,              ),            ),          ],        ),      ),    );  }}/// Trend indicator widgetclass TrendIndicator extends StatelessWidget {  final TrendData trend;  const TrendIndicator({    Key? key,    required this.trend,  }) : super(key: key);  @override  Widget build(BuildContext context) {    final isPositive = trend.isPositive;    final color = isPositive ? AppColors.success : AppColors.error;    final icon = isPositive ? Icons.trending_up : Icons.trending_down;    return Container(      padding: const EdgeInsets.symmetric(        horizontal: AppSpacing.xs,        vertical: 2,      ),      decoration: BoxDecoration(        color: color.withOpacity(0.1),        borderRadius: BorderRadius.circular(AppSpacing.xs),      ),      child: Row(        mainAxisSize: MainAxisSize.min,        children: [          Icon(            icon,            color: color,            size: 12,          ),          const SizedBox(width: 2),          Text(            '${trend.percentage}%',            style: AppTypography.labelSmall.copyWith(              color: color,              fontWeight: FontWeight.w600,            ),          ),        ],      ),    );  }}// Data modelsclass StatItem {  final String value;  final String label;  final IconData icon;  final Color color;  final TrendData? trend;  const StatItem({    required this.value,    required this.label,    required this.icon,    required this.color,    this.trend,  });}class ActivityItem {  final String title;  final String? subtitle;  final String timestamp;  final IconData icon;  final Color color;  const ActivityItem({    required this.title,    this.subtitle,    required this.timestamp,    required this.icon,    required this.color,  });}class QuickAction {  final String label;  final IconData icon;  final Color color;  final VoidCallback onTap;  const QuickAction({    required this.label,    required this.icon,    required this.color,    required this.onTap,  });}class TrendData {  final double percentage;  final bool isPositive;  const TrendData({    required this.percentage,    required this.isPositive,  });}/// Enhanced dashboard layout widgetclass EnhancedDashboard extends StatelessWidget {  final List<StatItem> stats;  final List<ActivityItem> activities;  final List<QuickAction> quickActions;  final Widget? personalizedContent;  const EnhancedDashboard({    Key? key,    required this.stats,    required this.activities,    required this.quickActions,    this.personalizedContent,  }) : super(key: key);  @override  Widget build(BuildContext context) {    return SingleChildScrollView(      padding: const EdgeInsets.all(AppSpacing.md),      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          // Quick Stats Section          DashboardComponents.buildQuickStats(stats: stats),          AppSpacing.gapMD,                    // Personalized Content          if (personalizedContent != null) ...[            personalizedContent!,            AppSpacing.gapMD,          ],                    // Recent Activity          DashboardComponents.buildActivityFeed(            activities: activities,            onViewAll: () {              // Navigate to full activity list            },          ),          AppSpacing.gapMD,                    // Quick Actions          DashboardComponents.buildQuickActions(actions: quickActions),        ],      ),    );  }}